import React, { useEffect, useState } from 'react';
import { Link as RouterLink } from "react-router-dom";
import Container from "@material-ui/core/Container";
import Grid from '@material-ui/core/Grid';
import useStyles from "../../assets/js/useStyles";
import { connect } from "react-redux";
//import contant data
import { getCardDummyJson, GetDashboard } from "../../actions/news";
import Skeleton from 'react-loading-skeleton';
import 'react-loading-skeleton/dist/skeleton.css';

//Import Component
import FeedRightbar from "../../components/FeedRightbar";
import closeIcon from '../../assets/images/close-icon.svg'
import data from '../../data.json';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import Button from '@mui/material/Button';
import Divider from '@mui/material/Divider';
import ListItem from '@mui/material/ListItem';
import ListItemText from '@mui/material/ListItemText';

function HomePage(props) {

    const [drawerData, setDrawerData] = useState([]);
    const [drawerState, setDrawerState] = useState({ right: false });
    const [tabDummyData, setTabDummyData] = useState(null);
    const toggleDrawer = (anchor, open, data = null) => (event) => {
        if (event.type === 'keydown' && (event.key === 'Tab' || event.key === 'Shift')) {
            return;
        }
        setDrawerState({ ...drawerState, [anchor]: open });
        if (data) setDrawerData(data);
    };

    const list = (anchor) => (
        <Drawer
            anchor={anchor}
            open={drawerState[anchor]}
            onClose={toggleDrawer(anchor, false)}
            BackdropProps={{
                sx: {
                    backgroundColor: "rgb(255 255 255 / 0.3)",
                    filter: "blur(8px)",
                    WebkitBackdropFilter: "blur(4px)",
                    transition: "all 0.3s ease-in-out",
                },
            }}
            PaperProps={{
                sx: {
                    backgroundColor: "rgba(255, 255, 255, 0.85)",
                    backdropFilter: "blur(8px)",
                    WebkitBackdropFilter: "blur(8px)",
                    borderRadius: "12px 0 0 12px",
                    boxShadow: "0 6px 24px rgba(0, 0, 0, 0.12)",
                },
            }}
        >
            <Box
                sx={{ width: anchor === 'top' || anchor === 'bottom' ? 'auto' : 850 }}
                role="presentation"
                onKeyDown={toggleDrawer(anchor, false)}
                style={{ paddingLeft: '18px', paddingRight: '18px' }}
            >
                <div
                    style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        marginTop: '18px',
                    }}
                    onClick={toggleDrawer(anchor, false)}
                >
                    <img
                        src={closeIcon}
                        alt='close icon'
                        style={{ width: '16px', height: '16px', cursor: 'pointer' }}
                    />
                </div>

                <h3 style={{ marginBottom: '30px', marginTop: '30px' }}>
                    {drawerData?.title}
                </h3>
                <Divider />

                {drawerData ? (
                    <div>
                        <div>
                            <p>
                                <div
                                    dangerouslySetInnerHTML={{
                                        __html: drawerData["content:encoded"] || drawerData.content,
                                    }}
                                ></div>
                            </p>
                        </div>
                        <Divider />
                        <ListItem>
                            <ListItemText
                                primary={`Author: ${drawerData.author}`}
                                secondary={`Published: ${drawerData.pubDate}`}
                            />
                        </ListItem>
                    </div>
                ) : (
                    <ListItem>
                        <ListItemText primary="No data available" />
                    </ListItem>
                )}
            </Box>
        </Drawer>
    );


    // const [state, setState] = React.useState({
    //     right: false,
    // });

    // const toggleDrawer = (anchor, open) => (event) => {
    //     if (event.type === 'keydown' && (event.key === 'Tab' || event.key === 'Shift')) {
    //         return;
    //     }

    //     setState({ ...state, [anchor]: open });
    // };

    // const list = (anchor) => (
    //     <Box
    //         sx={{ width: anchor === 'top' || anchor === 'bottom' ? 'auto' : 250 }}
    //         role="presentation"
    //         onClick={toggleDrawer(anchor, false)}
    //         onKeyDown={toggleDrawer(anchor, false)}
    //     >
    //     </Box>
    // );

    const {
        conetent,
        heading,
        LatestArticles,
        hrstyle,
        imagewdth
    } = useStyles();

    const [feedData, setFeedData] = useState({
        title: "",
        contents: "",
        image: "",
        link: ""
    });

    const [themeMode, setThemeMode] = useState(props.themeMode);
    const [active, setActive] = useState("Latest articles");

    const tabs = [
        { value: "Latest articles", label: "Latest articles" },
        { value: "3 Tech Stocks to Buy", label: "3 Tech Stocks to Buy" },
        { value: "5 Stocks to Watch This Week", label: "5 Stocks to Watch This Week" },
        { value: "Top Dividend Stocks Right Now", label: "Top Dividend Stocks Right Now" }
    ];

    useEffect(() => {
        window.scrollTo({ top: 0 });
        props.GetDashboard();
    }, []);

    useEffect(() => {
        setFeedData(props.feedData)
    }, [props.feedData]);

    useEffect(() => {
        if (props.themeMode != themeMode) {
            setThemeMode(props.themeMode)
        }
    }, [props.themeMode]);

    useEffect(() => {
        if (props.marketWatchMain) {
            setFeedData(props.marketWatchMain)
        }

    }, [props.marketWatchMain]);


    const fetchData = async () => {
        const res = await props.getCardDummyJson();
        setTabDummyData(res);
    };

    useEffect(() => {
        fetchData();
    }, []);


    const getCardLists = (latestArticlesList) => {
        return latestArticlesList.map(({ link, image, title, contents, social_links, list_contents, uuid }, index) => {
            const contentsData = contents.length != 0 ? contents[0].replaceAll("\n\n", "") : ""
            return (
                <RouterLink
                    className='card-list-link'
                    to={{
                        pathname: `/story/${uuid}`,
                        state: {
                            index,
                            title,
                            image,
                            contents,
                            contentsData,
                            link,
                            social_links,
                            list_contents
                        }
                    }}>
                    <div key={index}>
                        <div className='card-list'>
                            <div className="image-card" >
                                <img src={image} width="218" height="150" className={`${imagewdth}`} />
                                <div className='image-body'>
                                    <p className='text-primary'>{title}</p>
                                    <p className='text-secondary'> {contentsData}</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </RouterLink>
            );
        });
    }

    const getCardLoader = () => {
        const baseColor = themeMode == "light" ? "#0e0e0e" : "#ebebeb";
        const highlightColor = themeMode == "light" ? "#061727" : "#f5f5f5";
        return [1, 2, 3, 4].map(() => {
            return (
                <div className="post">
                    <div className="left-col">
                        <div className="avatar">
                            <Skeleton
                                baseColor={baseColor}
                                highlightColor={highlightColor}
                                height="100%"
                                containerClassName="avatar-skeleton"
                            />
                        </div>
                        <div className="user-name">
                            <Skeleton
                                baseColor={baseColor}
                                highlightColor={highlightColor}
                                width={150} />
                        </div>
                    </div>
                    <div className="right-col">
                        <>
                            <Skeleton
                                baseColor={baseColor}
                                highlightColor={highlightColor}
                                height="100%"
                                width={"551px"}
                                count={1} />
                        </>
                    </div>
                </div>
            )
        })
    }

    const getCardLists3 = () => {
        return tabDummyData?.items?.slice(0, 3)?.map((data, index) => {
            return (
                <RouterLink
                    className='card-list-link'
                >
                    <div key={index} style={{ marginLeft: '5px' }}>
                        <div style={{
                            background: "#fff", borderRadius: '8px', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)', padding: '16px',
                            width: '90%', marginTop: '20px',
                        }}>
                            <p className='text-primary' style={{ color: '#3E3E3E', fontWeight: 'bolder' }}>{data?.title}</p>
                            <p className='text-secondary' style={{ color: '#3E3E3E', fontWeight: 'bolder', fontSize: '14px' }}> {data?.content}</p>
                            <div style={{ display: 'flex', justifyContent: 'end' }}>
                                <Button onClick={toggleDrawer('right', true, data)}>
                                    View Details
                                </Button>
                                <Drawer
                                    anchor="right"
                                    open={drawerState.right}
                                    onClose={toggleDrawer('right', false)}
                                >
                                    {list('right')}
                                </Drawer>
                            </div>
                            {/* <div>
                                {['left', 'right', 'top', 'bottom'].map((anchor) => (
                                    <React.Fragment key={anchor}>
                                        <Button onClick={toggleDrawer(anchor, true)}>{anchor}</Button>
                                        <Drawer
                                            anchor={anchor}
                                            open={state[anchor]}
                                            onClose={toggleDrawer(anchor, false)}
                                        >
                                            {list(anchor)}
                                        </Drawer>
                                    </React.Fragment>
                                ))}
                            </div> */}
                        </div>
                    </div>
                </RouterLink>
            );
        });
    }

    const getCardLists5 = () => {
        return tabDummyData?.items?.slice(4, 9)?.map((data, index) => {
            return (
                <RouterLink
                    className='card-list-link'
                >
                    <div key={index} style={{ marginLeft: '5px' }}>
                        <div style={{
                            background: "#fff", borderRadius: '8px', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)', padding: '16px',
                            width: '90%', marginTop: '20px',
                        }}>
                            <p className='text-primary' style={{ color: '#3E3E3E', fontWeight: 'bolder' }}>{data.title}</p>
                            <p className='text-secondary' style={{ color: '#3E3E3E', fontWeight: 'bolder', fontSize: '14px' }}> {data.content}</p>
                            <div style={{ display: 'flex', justifyContent: 'end' }}>

                                <Button onClick={toggleDrawer('right', true, data)}>
                                    View Details
                                </Button>
                                <Drawer
                                    anchor="right"
                                    open={drawerState.right}
                                    onClose={toggleDrawer('right', false)}
                                >
                                    {list('right')}
                                </Drawer>
                            </div>
                        </div>
                    </div>
                </RouterLink>
            );
        });
    }

    const getCardListsTopDividend = () => {
        if (!data?.items || data.items.length < 9) {
            return null;
        }
        return tabDummyData?.items.slice(9).map((data, index) => {
            return (
                <RouterLink
                    className='card-list-link'
                >
                    <div key={index} style={{ marginLeft: '5px' }}>
                        <div style={{
                            background: "#fff", borderRadius: '8px', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)', padding: '16px',
                            width: '90%', marginTop: '20px',
                        }}>
                            <p className='text-primary' style={{ color: '#3E3E3E', fontWeight: 'bolder' }}>{data.title}</p>
                            <p className='text-secondary' style={{ color: '#3E3E3E', fontWeight: 'bolder', fontSize: '14px' }}> {data.content}</p>
                            <div style={{ display: 'flex', justifyContent: 'end' }}>

                                <Button onClick={toggleDrawer('right', true, data)}>
                                    View Details
                                </Button>
                                <Drawer
                                    anchor="right"
                                    open={drawerState.right}
                                    onClose={toggleDrawer('right', false)}
                                >
                                    {list('right')}
                                </Drawer>
                            </div>
                        </div>
                    </div>
                </RouterLink>
            );
        });
    }

    const baseColor = themeMode == "dark" ? "#0e0e0e" : "#ebebeb";
    const highlightColor = themeMode == "dark" ? "#061727" : "#f5f5f5";
    const contentsData = feedData.contents.length != 0 ? feedData.contents[0].split("\n\n")[0] : ""
    const page = window.location.pathname.replaceAll("/", "")
    return (
        <Container maxWidth="lg" className={conetent}>
            {/* <div>
                {['right'].map((anchor) => (
                    <React.Fragment key={anchor}>
                        <Button onClick={toggleDrawer(anchor, true)}>{anchor}</Button>
                        <Drawer
                            anchor={anchor}
                            open={state[anchor]}
                            onClose={toggleDrawer(anchor, false)}
                        >
                            {list(anchor)}
                        </Drawer>
                    </React.Fragment>
                ))}
            </div> */}
            <main>
                <div className='ads'>
                    <div id={`io_165143fcac3a71${page}`}></div>
                </div>
                <Grid container className='selection-one'>
                    <Grid item lg={8} sm={12} alignItems={'center'} justifyContent={'space-between'} className='grid-one' >
                        <div className="top-news-card">
                            <RouterLink
                                className='card-list-link'
                                to={{
                                    pathname: `/story/${feedData.uuid}`,
                                    state: {
                                        title: feedData.title,
                                        image: feedData.image,
                                        contents: feedData.contents,
                                        contentsData: feedData.contents,
                                        list_contents: feedData.list_contents,
                                        link: feedData.link,
                                        social_links: feedData.social_links
                                    }
                                }}>

                                {feedData.image != "" && <img src={feedData.image} className="home-amazon-image" />}
                                {feedData.image == "" &&
                                    <Skeleton
                                        baseColor={baseColor}
                                        highlightColor={highlightColor}
                                        width={"100%"}
                                        height={"437px"}
                                    />
                                }
                                {feedData.image != "" && <>
                                    <h2 className={`${heading} sm-font-size`}  >{feedData.title}</h2>
                                    <p className='simple-text'>{contentsData}</p>
                                </>}
                            </RouterLink>
                            {feedData.image == "" &&
                                <Skeleton
                                    baseColor={baseColor}
                                    highlightColor={highlightColor}
                                    width={"100%"}
                                    height={"98px"}
                                />
                            }
                        </div>
                        <div>
                            <div style={{ display: 'flex', marginTop: '36px' }}>
                                {tabs.map((t) => (
                                    <button
                                        key={t.value}
                                        onClick={() => setActive(t?.value)}
                                        className={`tabList ${active === t.value
                                            ? "tabActive"
                                            : "tabNotActive"
                                            }`}
                                    >
                                        {t.label}
                                    </button>
                                ))}
                            </div>
                            <hr className={hrstyle} />

                            {(active === "Latest articles") && <>
                                <div style={{ height: "672px", overflowY: 'scroll', width: '91%' }} className="scrollbar">
                                    {props.marketWatchLatest.length != 0 && getCardLists(props.marketWatchLatest)}
                                    {props.marketWatchLatest.length == 0 && getCardLoader()}
                                </div>
                            </>}
                            {(active === "3 Tech Stocks to Buy") && <>
                                <div style={{ height: "672px", overflowY: 'scroll', width: '91%' }} className="scrollbar">
                                    {getCardLists3()}
                                </div>
                            </>}
                            {(active === "5 Stocks to Watch This Week") && <>
                                <div style={{ height: "672px", overflowY: 'scroll', width: '91%' }} className="scrollbar">
                                    {getCardLists5()}
                                </div></>}
                            {(active === "Top Dividend Stocks Right Now") && <>
                                <div style={{ height: "672px", overflowY: 'scroll', width: '91%' }} className="scrollbar">
                                    {getCardListsTopDividend()}
                                </div>
                            </>}

                        </div>
                    </Grid>
                    <Grid item lg={4} sm={12}>
                        <FeedRightbar />
                    </Grid>
                </Grid>
            </main>
        </Container >
    );
}

const mapStateToProps = ({ reducer }) => {
    return {
        feedData: reducer.feedData,
        themeMode: reducer.themeMode,
        latestArticlesList: reducer.latestArticlesList,
        marketWatchMain: reducer.marketWatchMain,
        marketWatchLatest: reducer.marketWatchLatest,
    };
}

const mapDispatchToProps = (dispatch) => {
    return {
        GetDashboard: () => dispatch(GetDashboard()),
        getCardDummyJson: () => dispatch(getCardDummyJson())
    };
}


export default connect(mapStateToProps, mapDispatchToProps)(HomePage);
